// Semantic Colors
$eduxa-success: #10b981;        // Emerald-500
$eduxa-success-light: #34d399;
$eduxa-success-dark: #059669;
$eduxa-success-50: #ecfdf5;
$eduxa-success-100: #d1fae5;
$eduxa-success-200: #a7f3d0;
$eduxa-success-300: #6ee7b7;
