// Typography
$eduxa-font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
$eduxa-font-size-xs: 0.75rem;    // 12px
$eduxa-font-size-sm: 0.875rem;   // 14px
$eduxa-font-size-base: 1rem;     // 16px
$eduxa-font-size-lg: 1.125rem;   // 18px
$eduxa-font-size-xl: 1.25rem;    // 20px
