$eduxa-font-weight-light: 300;
$eduxa-font-weight-normal: 400;
$eduxa-font-weight-medium: 500;
$eduxa-font-weight-semibold: 600;
$eduxa-font-weight-bold: 700;

$eduxa-line-height-tight: 1.25;
$eduxa-line-height-normal: 1.5;
$eduxa-line-height-relaxed: 1.75;

// Spacing
$eduxa-spacing-0: 0;
$eduxa-spacing-1: 0.25rem;   // 4px
$eduxa-spacing-2: 0.5rem;    // 8px
$eduxa-spacing-3: 0.75rem;   // 12px
$eduxa-spacing-4: 1rem;      // 16px
