  --eduxa-secondary-100: #{$eduxa-secondary-100};
  --eduxa-secondary-200: #{$eduxa-secondary-200};
  --eduxa-secondary-300: #{$eduxa-secondary-300};
  --eduxa-secondary-400: #{$eduxa-secondary-400};
  --eduxa-secondary-500: #{$eduxa-secondary-500};
  --eduxa-secondary-600: #{$eduxa-secondary-600};
