// Base styles
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--eduxa-font-family);
  font-size: var(--eduxa-font-size-base);
  line-height: var(--eduxa-line-height-normal);
  color: var(--eduxa-gray-900);
  background-color: var(--eduxa-gray-50);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

// Dark mode
.dark-mode {
  background-color: var(--eduxa-dark-surface);
  color: var(--eduxa-dark-text);
}

// Animations
@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes slideUp {
  from {
    transform: translateY(20px);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

@keyframes slideDown {
  from {
    transform: translateY(-20px);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

@keyframes pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

@keyframes spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

.animate-fade-in {
  animation: fadeIn var(--eduxa-transition-base) ease-out;
}

.animate-slide-up {
  animation: slideUp var(--eduxa-transition-slow) ease-out;
}

.animate-slide-down {
  animation: slideDown var(--eduxa-transition-slow) ease-out;
}

.animate-pulse {
  animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}

.animate-spin {
  animation: spin 1s linear infinite;
}

// Scrollbar styling
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--eduxa-gray-100);
  border-radius: var(--eduxa-radius-md);
}

::-webkit-scrollbar-thumb {
  background: var(--eduxa-gray-300);
  border-radius: var(--eduxa-radius-md);

  &:hover {
    background: var(--eduxa-gray-400);
  }
}

.dark-mode ::-webkit-scrollbar-track {
  background: var(--eduxa-dark-surface);
}

.dark-mode ::-webkit-scrollbar-thumb {
  background: var(--eduxa-dark-border);

  &:hover {
    background: var(--eduxa-gray-600);
  }
}

// Eduxa Design System - Main Index
// Central entry point for the design system

// Components
export * from './components'

// Styles (imported via Vite config)
import './styles/main.scss'

// Design tokens (can be used in TypeScript)
export const designTokens = {
  colors: {
    primary: '#6366f1',
    primaryLight: '#818cf8',
    primaryDark: '#4f46e5',
    secondary: '#0ea5e9',
    secondaryLight: '#38bdf8',
